#!/usr/bin/env node
/**
 * 元数据清理：只清除"暴露由程序/AI 生成"的痕迹，保留正常的办公软件元数据。
 *
 * 清除对象（可逐项关闭）：
 *   - dc:creator / cp:lastModifiedBy 中的生成器签名（python-docx、LibreOffice、Pandoc…）
 *   - dc:description 里的 generated by / AI 工具自述
 *   - 模板自带的假时间（python-docx 固定 2013-12-23T23:15:00Z）、created 与 modified 完全相同
 *   - Application 与实际运行平台矛盾的取值（见 PLATFORM_APP_RULES，v0.7.2 起跨平台）
 *   - TotalTime 与字数统计全为 0 的"未编辑"特征
 *   - docProps/thumbnail.jpeg（模板缩略图，与实际内容无关）
 *   - word/settings.xml 的 rsids 与各处的 rsid 属性（大量编辑会话痕迹）
 *
 * 刻意保留：Template=Normal.dotm、空 Company/Manager、真实作者名（不在签名库内）、
 * 文档内容与样式、批注与修订（属于内容，不属于元数据）。
 */
'use strict';

const { XML_DECL, escapeText, unescapeXml, readTag } = require('./xml');
const { documentStats } = require('./clean');

const CORE_PART = 'docProps/core.xml';
const APP_PART = 'docProps/app.xml';
const CORE_REL = 'http://schemas.openxmlformats.org/package/2006/relationships/metadata/core-properties';
const CORE_CT = 'application/vnd.openxmlformats-package.core-properties+xml';
const APP_REL = 'http://schemas.openxmlformats.org/officeDocument/2006/relationships/extended-properties';
const APP_CT = 'application/vnd.openxmlformats-officedocument.extended-properties+xml';

const CORE_NS = 'xmlns:cp="http://schemas.openxmlformats.org/package/2006/metadata/core-properties" ' +
  'xmlns:dc="http://purl.org/dc/elements/1.1/" ' +
  'xmlns:dcterms="http://purl.org/dc/terms/" ' +
  'xmlns:dcmitype="http://purl.org/dc/dcmitype/" ' +
  'xmlns:xsi="http://www.w3.org/2001/XMLSchema-instance"';

const GENERATOR_PATTERNS = [
  /python-docx/i, /(^|[^a-z])docx([^a-z]|$)/i, /python/i, /libreoffice/i, /openoffice/i,
  /apache\s*poi/i, /docx4j/i, /pandoc/i, /mammoth/i, /docxtemplater/i, /officegen/i,
  /generated\s+by/i, /auto[-_ ]?generated/i, /chatgpt/i, /openai/i, /anthropic/i, /claude/i,
  /deepseek/i, /copilot/i, /aigc/i,
];

const PLACEHOLDER_TIMES = [
  '2013-12-23T23:15:00Z', // python-docx 默认模板
  '2013-12-23T23:15:00.000Z',
];

/**
 * Application 字段的「平台矛盾」判定表（v0.7.2 起跨平台）。
 *
 * 目标基线固定为 Windows 版 Word（DEFAULT_OPTIONS.application 即该取值），
 * 因为交付对象基本是 Windows Word 收件人。表里只列「本机不可能产出、
 * 又不属于目标基线」的取值，避免把真实的跨平台协作痕迹当垃圾清掉。
 *
 *   win32   Macintosh 版 Word 的签名 → 矛盾（本机是 Windows Word）
 *   linux   本机没有 Word，Macintosh 签名只可能来自模板 → 同 Windows 口径归一
 *   darwin  Mac Word 签名合理 → 不判矛盾，保留真实作者平台
 *
 * 未列出的平台（freebsd、aix…）按 linux 口径处理：本机同样产不出 Mac Word。
 * 判定只看 process.platform（或调用方注入的 platform），不探测系统装了哪些
 * 办公软件 —— 探测得到的结论依赖本机环境，反而不可复现。
 *
 * 实现要点：早期版本把 `process.platform === 'win32'` 硬编码在清理与诊断两处，
 * 导致 Linux/macOS 上同一逻辑永不生效、回归用例在非 Windows 机器上必然失败。
 * 现改为「表 + 可注入平台」：规则集中一处，测试可在任意宿主上确定性地覆盖三条分支。
 */
const PLATFORM_APP_RULES = {
  win32: /macintosh/i,
  linux: /macintosh/i,
  darwin: null,
};

/**
 * Application 的取值是否与运行平台矛盾。
 * @param {string} application app.xml 里的 Application 文本
 * @param {string} [platform] 默认 process.platform；可注入以便测试
 * @returns {boolean}
 */
function isAppPlatformMismatch(application, platform) {
  if (!application) return false;
  const host = platform || process.platform;
  const rule = Object.prototype.hasOwnProperty.call(PLATFORM_APP_RULES, host)
    ? PLATFORM_APP_RULES[host]
    : PLATFORM_APP_RULES.linux;
  return !!(rule && rule.test(String(application)));
}

const DEFAULT_OPTIONS = {
  author: '',            // 空字符串 = 清空作者；填名字则写入该名字
  lastModifiedBy: null,  // null = 跟随 author
  resetTimes: true,      // 重设创建/修改时间
  application: 'Microsoft Office Word',
  appVersion: '16.0000',
  platform: null,        // null = 跟随 process.platform；可显式传 'win32'/'darwin'/'linux'
  dropThumbnail: true,
  clearRsids: true,
  fillStats: true,
  extraPatterns: [],
  now: null,
};

function isGeneratorValue(value, extra) {
  if (!value) return false;
  const text = String(value).trim();
  if (!text) return false;
  const patterns = GENERATOR_PATTERNS.concat(extra || []);
  return patterns.some((re) => re.test(text));
}

function w3cdtf(date) {
  return date.toISOString().replace(/\.\d{3}Z$/, 'Z');
}



function writeTag(xml, tag, value) {
  const open = new RegExp('<' + tag + '(\\s[^>]*)?>([\\s\\S]*?)</' + tag + '>');
  if (open.test(xml)) {
    return xml.replace(open, (whole, attrs) => '<' + tag + (attrs || '') + '>' + escapeText(value) + '</' + tag + '>');
  }
  const selfClosing = new RegExp('<' + tag + '(\\s[^>]*)?/>');
  if (selfClosing.test(xml)) {
    return xml.replace(selfClosing, (whole, attrs) => '<' + tag + (attrs || '') + '>' + escapeText(value) + '</' + tag + '>');
  }
  return xml.replace('</cp:coreProperties>', '<' + tag + '>' + escapeText(value) + '</' + tag + '></cp:coreProperties>');
}

function removeTag(xml, tag) {
  const re = new RegExp('<' + tag + '(?:\\s[^>]*)?>[\\s\\S]*?</' + tag + '>|<' + tag + '(?:\\s[^>]*)?/>', 'g');
  return xml.replace(re, '');
}

function buildCoreXml(opts, now) {
  const author = opts.author || '';
  const lastBy = opts.lastModifiedBy === null ? author : opts.lastModifiedBy;
  const times = buildTimes(now);
  return XML_DECL + '<cp:coreProperties ' + CORE_NS + '>' +
    (author ? '<dc:creator>' + escapeText(author) + '</dc:creator>' : '<dc:creator/>') +
    '<cp:lastModifiedBy>' + escapeText(lastBy || '') + '</cp:lastModifiedBy>' +
    '<cp:revision>1</cp:revision>' +
    '<dcterms:created xsi:type="dcterms:W3CDTF">' + w3cdtf(times.created) + '</dcterms:created>' +
    '<dcterms:modified xsi:type="dcterms:W3CDTF">' + w3cdtf(times.modified) + '</dcterms:modified>' +
    '</cp:coreProperties>';
}

/**
 * 创建时间与修改时间必须不同：真实文档的 modified 一定晚于 created。
 * 偏移固定（不随机），保证同一输入多次运行结果一致。
 */
const CREATED_OFFSET_MINUTES = 37;

function buildTimes(now) {
  const modified = new Date(now.getTime());
  const created = new Date(now.getTime() - CREATED_OFFSET_MINUTES * 60000);
  return { created, modified };
}

function buildAppXml(opts, stats) {
  const parts = [
    '<Template>Normal.dotm</Template>',
    '<Application>' + escapeText(opts.application) + '</Application>',
    '<DocSecurity>0</DocSecurity>',
    '<ScaleCrop>false</ScaleCrop>',
  ];
  if (opts.fillStats) {
    parts.push('<Pages>1</Pages>');
    parts.push('<Words>' + stats.characters + '</Words>');
    parts.push('<Characters>' + stats.characters + '</Characters>');
    parts.push('<Lines>' + stats.lines + '</Lines>');
    parts.push('<Paragraphs>' + stats.paragraphs + '</Paragraphs>');
  }
  parts.push('<AppVersion>' + escapeText(opts.appVersion) + '</AppVersion>');
  parts.push('<Company/><LinksUpToDate>false</LinksUpToDate><SharedDoc>false</SharedDoc>' +
    '<HyperlinksChanged>false</HyperlinksChanged>');
  return XML_DECL + '<Properties xmlns="http://schemas.openxmlformats.org/officeDocument/2006/extended-properties" ' +
    'xmlns:vt="http://schemas.openxmlformats.org/officeDocument/2006/docPropsVTypes">' + parts.join('') + '</Properties>';
}

/**
 * 执行元数据清理。
 * @param {DocxPackage} pkg
 * @param {object} options
 * @param {Date} fileMtime 可选，用于时间回退
 * @returns {{changes:Array, removedParts:Array}}
 */
function cleanMetadata(pkg, options, fileMtime) {
  const opts = Object.assign({}, DEFAULT_OPTIONS, options || {});
  const now = opts.now ? new Date(opts.now) : (fileMtime ? new Date(fileMtime) : new Date());
  const changes = [];
  const removedParts = [];
  const stats = documentStats(pkg);

  // ---------- core.xml ----------
  let core = pkg.getText(CORE_PART);
  if (!core) {
    pkg.setText(CORE_PART, buildCoreXml(opts, now));
    pkg.ensureContentTypeOverride(CORE_PART, CORE_CT);
    pkg.ensureRel('', CORE_REL, CORE_PART);
    changes.push({ part: CORE_PART, action: 'create', detail: '补齐缺失的文档属性（正常 Word 文档必有）' });
  } else {
    const creator = readTag(core, 'dc:creator');
    if (isGeneratorValue(creator, opts.extraPatterns) || (opts.author && creator !== opts.author)) {
      core = writeTag(core, 'dc:creator', opts.author || '');
      changes.push({ part: CORE_PART, action: 'clear', detail: '作者字段原为生成器签名：' + (creator || '空') });
    }
    const lastBy = readTag(core, 'cp:lastModifiedBy');
    if (isGeneratorValue(lastBy, opts.extraPatterns)) {
      const target = opts.lastModifiedBy === null ? (opts.author || '') : opts.lastModifiedBy;
      core = writeTag(core, 'cp:lastModifiedBy', target);
      changes.push({ part: CORE_PART, action: 'clear', detail: '最后修改者为生成器签名：' + lastBy });
    }
    const desc = readTag(core, 'dc:description');
    if (isGeneratorValue(desc, opts.extraPatterns)) {
      core = removeTag(core, 'dc:description');
      changes.push({ part: CORE_PART, action: 'remove', detail: '描述自述由程序生成：' + desc });
    }
    if (opts.resetTimes) {
      const created = readTag(core, 'dcterms:created');
      const modified = readTag(core, 'dcterms:modified');
      const isPlaceholder = PLACEHOLDER_TIMES.includes(created) || PLACEHOLDER_TIMES.includes(modified);
      const identical = created && modified && created === modified;
      const tooOld = created && Number(created.slice(0, 4)) < 2000;
      if (isPlaceholder || identical || tooOld || !created) {
        const times = buildTimes(now);
        const createdStamp = w3cdtf(times.created);
        const modifiedStamp = w3cdtf(times.modified);
        core = /<dcterms:created/.test(core)
          ? core.replace(/<dcterms:created([^>]*)>[\s\S]*?<\/dcterms:created>/,
            '<dcterms:created$1>' + createdStamp + '</dcterms:created>')
          : writeTag(core, 'dcterms:created', createdStamp);
        core = /<dcterms:modified/.test(core)
          ? core.replace(/<dcterms:modified([^>]*)>[\s\S]*?<\/dcterms:modified>/,
            '<dcterms:modified$1>' + modifiedStamp + '</dcterms:modified>')
          : writeTag(core, 'dcterms:modified', modifiedStamp);
        changes.push({
          part: CORE_PART, action: 'reset',
          detail: '创建/修改时间可疑（' + (created || '缺失') + (identical ? '，且两者相同' : '') + '）已重设',
        });
      }
    }
    const rev = readTag(core, 'cp:revision');
    if (rev === null || rev === '' || Number(rev) < 1) {
      core = writeTag(core, 'cp:revision', '1');
      changes.push({ part: CORE_PART, action: 'reset', detail: '修订次数缺失或为 0，已置 1' });
    }
    pkg.setText(CORE_PART, core);
  }

  // ---------- app.xml ----------
  let app = pkg.getText(APP_PART);
  if (!app) {
    pkg.setText(APP_PART, buildAppXml(opts, stats));
    pkg.ensureContentTypeOverride(APP_PART, APP_CT);
    pkg.ensureRel('', APP_REL, APP_PART);
    changes.push({ part: APP_PART, action: 'create', detail: '补齐缺失的应用程序属性（正常 Word 文档必有）' });
  } else {
    const application = readTag(app, 'Application');
    if (isAppPlatformMismatch(application, opts.platform)) {
      app = writeTag(app, 'Application', opts.application);
      changes.push({
        part: APP_PART, action: 'reset',
        detail: 'Application 与运行平台（' + (opts.platform || process.platform) + '）矛盾：' + application,
      });
    }
    if (!readTag(app, 'AppVersion')) {
      app = app.replace('</Properties>', '<AppVersion>' + escapeText(opts.appVersion) + '</AppVersion></Properties>');
      changes.push({ part: APP_PART, action: 'create', detail: '补写 AppVersion' });
    }
    const totalTime = readTag(app, 'TotalTime');
    if (totalTime !== null && Number(totalTime) === 0) {
      app = removeTag(app, 'TotalTime');
      changes.push({ part: APP_PART, action: 'remove', detail: 'TotalTime=0（文档从未被编辑的特征）' });
    }
    if (opts.fillStats) {
      const zeros = ['Words', 'Characters', 'Lines', 'Paragraphs'].filter((t) => {
        const v = readTag(app, t);
        return v !== null && Number(v) === 0;
      });
      if (zeros.length) {
        app = writeTag(app, 'Words', String(stats.characters));
        app = writeTag(app, 'Characters', String(stats.characters));
        app = writeTag(app, 'Lines', String(stats.lines));
        app = writeTag(app, 'Paragraphs', String(stats.paragraphs));
        changes.push({ part: APP_PART, action: 'reset', detail: '统计全 0：' + zeros.join('/') + '，已按实际内容回填' });
      }
    }
    pkg.setText(APP_PART, app);
  }

  // ---------- 缩略图 ----------
  if (opts.dropThumbnail) {
    const thumb = 'docProps/thumbnail.jpeg';
    if (pkg.has(thumb)) {
      pkg.removeRelsByTarget('', thumb);
      pkg.removeContentTypeOverride(thumb);
      pkg.remove(thumb);
      removedParts.push(thumb);
      changes.push({
        part: thumb, action: 'remove',
        detail: '模板缩略图：与实际内容无关，是生成器套用模板的典型痕迹',
      });
    }
  }

  // ---------- rsid ----------
  if (opts.clearRsids) {
    let cleared = 0;
    for (const name of pkg.order.slice()) {
      if (!/^word\/.*\.xml$/.test(name)) continue;
      const text = pkg.getText(name);
      if (!text || !/rsid/i.test(text)) continue;
      let out = text.replace(/<w:rsids>[\s\S]*?<\/w:rsids>/g, '');
      out = out.replace(/\sw:rsid[A-Za-z]*="[^"]*"/g, '');
      if (out !== text) {
        pkg.setText(name, out);
        cleared += 1;
      }
    }
    if (cleared) {
      changes.push({ part: 'word/*.xml', action: 'clear', detail: '清除 ' + cleared + ' 个部件中的 rsid 编辑会话标记' });
    }
  }

  return { changes, removedParts, stats };
}

module.exports = {
  cleanMetadata, DEFAULT_OPTIONS, isGeneratorValue, GENERATOR_PATTERNS,
  CORE_PART, APP_PART, buildCoreXml, buildAppXml,
  PLATFORM_APP_RULES, isAppPlatformMismatch,
};
